        const auto self=weak.lock();const auto value=item.lock();if(!self||!value||value->closed||value->credential_private||!self->agent_control(value->thread_id))return;
        try{const auto bytes=winrt::to_string(args.ParameterObjectAsJson());if(bytes.size()>65536)return;const auto event=browser_json::JsonObject::Parse(winrt::to_hstring(bytes));browser_json::JsonObject line;browser_tool::put(line,L"type",winrt::to_string(event.GetNamedString(L"type",L"log")).substr(0,32));std::string message;
            for(const auto& raw:event.GetNamedArray(L"args",browser_json::JsonArray{})){const auto arg=raw.GetObject();if(!arg.HasKey(L"value"))continue;const auto primitive=arg.GetNamedValue(L"value");if(primitive.ValueType()==browser_json::JsonValueType::Object||primitive.ValueType()==browser_json::JsonValueType::Array)continue;if(!message.empty())message+=' ';message+=primitive.ValueType()==browser_json::JsonValueType::String?winrt::to_string(primitive.GetString()):winrt::to_string(primitive.Stringify());if(message.size()>1024){message.resize(1024);break;}}
            browser_tool::put(line,L"text",message);if(value->console.size()>=200)value->console.erase(value->console.begin());value->console.push_back(line);
        }catch(...){}
